import { describe, expect, it } from "vitest";
import { groupByMonth } from "./groupByMonth";

const orders = [
  { id: 1, placedAt: new Date("2026-01-14T10:00:00Z") },
  { id: 2, placedAt: new Date("2026-01-30T10:00:00Z") },
  { id: 3, placedAt: new Date("2026-02-02T10:00:00Z") },
];

describe("groupByMonth", () => {
  it("buckets orders by YYYY-MM", () => {
    const expected: Record<string, number[]> = {};
    for (const o of orders) {
      const key = `${o.placedAt.getUTCFullYear()}-${String(o.placedAt.getUTCMonth() + 1).padStart(2, "0")}`;
      (expected[key] ??= []).push(o.id);
    }
    expect(groupByMonth(orders)).toEqual(expected);
  });
});

